package com.graduation.rental.domain;import com.graduation.rental.auth.AuthService;import com.graduation.rental.common.ApiException;import org.springframework.web.bind.annotation.*;import java.time.*;import java.util.*;
@RestController @RequestMapping("/api/appointments")public class AppointmentController{private final ViewingAppointmentRepository repo;private final RentalListingRepository listings;private final AuthService auth;public AppointmentController(ViewingAppointmentRepository r,RentalListingRepository l,AuthService a){repo=r;listings=l;auth=a;}public record Create(@jakarta.validation.constraints.NotNull @jakarta.validation.constraints.Positive Long listingId,@jakarta.validation.constraints.NotNull @jakarta.validation.constraints.Future LocalDateTime visitTime,@jakarta.validation.constraints.Size(max=1000) String note){}@PostMapping public ViewingAppointment create(@jakarta.validation.Valid @RequestBody Create x){listings.findById(x.listingId()).orElseThrow(()->ApiException.notFound("房源不存在"));if(x.visitTime()==null||x.visitTime().isBefore(LocalDateTime.now()))throw ApiException.badRequest("看房时间必须在未来");var a=new ViewingAppointment();a.setListingId(x.listingId());a.setUserId(auth.currentUser().getId());a.setVisitTime(x.visitTime());a.setNote(x.note());a.setStatus("PENDING");return repo.save(a);}@GetMapping public List<ViewingAppointment> list(){var u=auth.currentUser();return "ADMIN".equals(u.getRole())?repo.findAll(org.springframework.data.domain.PageRequest.of(0,200,org.springframework.data.domain.Sort.by(org.springframework.data.domain.Sort.Direction.DESC,"id"))).getContent():repo.findTop200ByUserIdOrderByIdDesc(u.getId());}}
